// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

/// @notice Shared upgrade authorization. Production deployments must assign upgradeAuthority
/// to the approved governance/recovery route, not an externally controlled hot wallet.
abstract contract CatalystUUPS is Initializable, UUPSUpgradeable {
    address public upgradeAuthority;

    error Unauthorized();
    error ZeroAddress();

    modifier onlyUpgradeAuthority() {
        if (msg.sender != upgradeAuthority) revert Unauthorized();
        _;
    }

    function __CatalystUUPS_init(address authority) internal onlyInitializing {
        if (authority == address(0)) revert ZeroAddress();
        upgradeAuthority = authority;
    }

    function _authorizeUpgrade(address) internal view virtual override onlyUpgradeAuthority {}

    /// @dev Deliberately disable generic role-management patterns in core contracts.
    /// Implementations use explicit, bounded configuration functions instead.
}

contracts/governance/CatalystGovernance..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CatalystUUPS} from "../common/CatalystUUPS.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";

/// @notice Minimal, explicit governance executor. Proposal payloads are committed at creation;
/// production rollout must complete BWCG historical-snapshot integration and parameter simulations.
contract CatalystGovernance is CatalystUUPS, ReentrancyGuardUpgradeable {
    uint64 public constant VOTING_PERIOD = 7 days;
    uint64 public constant EXECUTION_DELAY = 48 hours;
    uint64 public constant EXECUTION_WINDOW = 14 days;
    uint256 public constant QUORUM_BPS = 1000;
    uint256 public constant COLLECTION_VOTE_CAP_BPS = 2000;

    enum Status { NONE, ACTIVE, QUEUED, EXECUTED, CANCELLED, EXPIRED }
    struct Proposal {
        address proposer;
        address target;
        uint64 createdAt;
        uint64 votingEndsAt;
        uint64 executeAfter;
        uint64 expiresAt;
        uint256 snapshotEligibleSupply;
        uint256 forVotes;
        uint256 againstVotes;
        uint256 abstainVotes;
        bytes32 callDataHash;
        Status status;
    }

    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => bool)) public hasVoted;
    uint256 public proposalCount;
    address public staking;
    uint256 public minimumProposalWeight;

    error InvalidProposal();
    error VotingClosed();
    error AlreadyVoted();
    error NotExecutable();
    error NotAuthorized();

    event ProposalCreated(uint256 indexed id, address indexed proposer, address indexed target, bytes32 callDataHash, uint64 votingEndsAt);
    event VoteCast(uint256 indexed id, address indexed voter, uint8 support, uint256 weight);
    event ProposalQueued(uint256 indexed id, uint64 executeAfter, uint64 expiresAt);
    event ProposalExecuted(uint256 indexed id, address indexed executor);

    constructor() { _disableInitializers(); }

    function initialize(address staking_, address upgradeAuthority_) external initializer {
        // Zero is permitted only during staged deployment; setStaking must be called before use.
        __ReentrancyGuard_init();
        __CatalystUUPS_init(upgradeAuthority_);
        staking = staking_;
        minimumProposalWeight = 1000 ether;
    }

    function setStaking(address staking_) external onlyUpgradeAuthority {
        require(staking == address(0) && staking_ != address(0), "staking configured");
        staking = staking_;
    }

    /// @dev proposer supplies the snapshot weight; the production release must replace this with
    /// on-chain BWCG snapshot computation and verify it against staking/burn checkpoints.
    function propose(address target, bytes calldata callData, uint256 proposerSnapshotWeight, uint256 snapshotEligibleSupply) external returns (uint256 id) {
        if (staking == address(0) || target == address(0) || callData.length == 0 || proposerSnapshotWeight < minimumProposalWeight || snapshotEligibleSupply == 0) revert InvalidProposal();
        id = ++proposalCount;
        uint64 end = uint64(block.timestamp + VOTING_PERIOD);
        proposals[id] = Proposal(msg.sender, target, uint64(block.timestamp), end, 0, 0, snapshotEligibleSupply, 0, 0, 0, keccak256(callData), Status.ACTIVE);
        emit ProposalCreated(id, msg.sender, target, keccak256(callData), end);
    }

    function vote(uint256 id, uint8 support, uint256 snapshotWeight) external {
        Proposal storage p = proposals[id];
        if (p.status != Status.ACTIVE || block.timestamp >= p.votingEndsAt) revert VotingClosed();
        if (hasVoted[id][msg.sender] || support > 2 || snapshotWeight == 0) revert AlreadyVoted();
        hasVoted[id][msg.sender] = true;
        if (support == 0) p.againstVotes += snapshotWeight;
        else if (support == 1) p.forVotes += snapshotWeight;
        else p.abstainVotes += snapshotWeight;
        emit VoteCast(id, msg.sender, support, snapshotWeight);
    }

    function queue(uint256 id) external {
        Proposal storage p = proposals[id];
        if (p.status != Status.ACTIVE || block.timestamp < p.votingEndsAt) revert NotExecutable();
        uint256 participation = p.forVotes + p.againstVotes + p.abstainVotes;
        require(participation * 10_000 >= p.snapshotEligibleSupply * QUORUM_BPS, "quorum not met");
        require(p.forVotes > p.againstVotes, "majority not met");
        p.status = Status.QUEUED;
        p.executeAfter = uint64(block.timestamp + EXECUTION_DELAY);
        p.expiresAt = p.executeAfter + EXECUTION_WINDOW;
        emit ProposalQueued(id, p.executeAfter, p.expiresAt);
    }

    function execute(uint256 id, bytes calldata callData) external nonReentrant {
        Proposal storage p = proposals[id];
        if (p.status != Status.QUEUED || block.timestamp < p.executeAfter || block.timestamp > p.expiresAt) revert NotExecutable();
        if (keccak256(callData) != p.callDataHash) revert InvalidProposal();
        p.status = Status.EXECUTED;
        (bool ok, bytes memory result) = p.target.call(callData);
        if (!ok) {
            p.status = Status.QUEUED;
            assembly { revert(add(result, 32), mload(result)) }
        }
        emit ProposalExecuted(id, msg.sender);
    }

    function setMinimumProposalWeight(uint256 value) external {
        if (msg.sender != upgradeAuthority) revert NotAuthorized();
        require(value > 0, "zero weight");
        minimumProposalWeight = value;
    }

    uint256[40] private __gap;
}

contracts/recovery/BatchGuardianCouncil..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CatalystUUPS} from "../common/CatalystUUPS.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";

/// @notice Guardian recovery coordinator. Only allowlisted targets/selectors may be executed.
/// Deployment must pre-seed both 7-member batches and set the last-honest guardian deterministically.
contract BatchGuardianCouncil is CatalystUUPS, ReentrancyGuardUpgradeable {
    uint256 public constant GUARDIANS = 7;
    uint256 public constant THRESHOLD = 5;
    uint256 public constant RECOVERY_DELAY = 4 hours;
    uint256 public constant VETO_WINDOW = 48 hours;
    uint256 public constant PROPOSAL_LIFETIME = 7 days;
    uint256 public constant RESEED_DELAY = 48 hours;

    address[7] public active;
    address[7] public standby;
    mapping(address => bool) public isActive;
    mapping(address => bool) public isStandby;
    mapping(address => bool) public approvedTarget;
    mapping(address => mapping(bytes4 => bool)) public approvedSelector;
    address public lastHonestGuardian;
    bool public locked;
    bool public warning;
    bool public standbyActivated;
    uint256 public nextRecoveryId;

    struct Recovery {
        address proposer;
        address target;
        bytes32 calldataHash;
        uint256 chainId;
        uint256 nonce;
        uint64 createdAt;
        uint64 executeAfter;
        uint64 expiresAt;
        uint8 approvals;
        bool vetoed;
        bool executed;
        mapping(address => bool) approved;
    }
    mapping(uint256 => Recovery) private recoveries;

    error NotGuardian();
    error InvalidRecovery();
    error NotReady();
    error TargetNotAllowed();
    error AlreadyApproved();
    error CouncilLocked();

    event RecoveryProposed(uint256 indexed id, address indexed proposer, address indexed target, bytes32 calldataHash, uint64 executeAfter, uint64 expiresAt);
    event RecoveryApproved(uint256 indexed id, address indexed guardian, uint8 approvals);
    event WarningActivated(uint256 indexed id, uint64 vetoEndsAt);
    event RecoveryVetoed(uint256 indexed id, address indexed guardian);
    event RecoveryExecuted(uint256 indexed id, address indexed executor);
    event CouncilLockedAndStandbyActivated();
    event GuardianBatchSeeded(bool indexed standbyBatch);
    event TargetAllowlisted(address indexed target, bytes4 indexed selector, bool allowed);

    constructor() { _disableInitializers(); }

    function initialize(address upgradeAuthority_, address lastHonestGuardian_) external initializer {
        require(lastHonestGuardian_ != address(0), "zero guardian");
        __ReentrancyGuard_init();
        __CatalystUUPS_init(upgradeAuthority_);
        lastHonestGuardian = lastHonestGuardian_;
        nextRecoveryId = 1;
    }

    function seedBatches(address[7] calldata active_, address[7] calldata standby_) external onlyUpgradeAuthority {
        require(!standbyActivated, "already activated");
        for (uint256 i; i < 7; ++i) {
            require(active_[i] != address(0) && standby_[i] != address(0), "zero guardian");
            for (uint256 j; j < i; ++j) {
                require(active_[i] != active_[j] && standby_[i] != standby_[j], "duplicate guardian");
            }
            require(active_[i] != standby_[i], "overlap");
            active[i] = active_[i]; standby[i] = standby_[i];
            isActive[active_[i]] = true; isStandby[standby_[i]] = true;
        }
        emit GuardianBatchSeeded(false);
        emit GuardianBatchSeeded(true);
    }

    function setAllowedSelector(address target, bytes4 selector, bool allowed) external onlyUpgradeAuthority {
        require(target != address(0), "zero target");
        approvedTarget[target] = allowed;
        approvedSelector[target][selector] = allowed;
        emit TargetAllowlisted(target, selector, allowed);
    }

    function proposeRecovery(address target, bytes calldata data, uint256 nonce) external returns (uint256 id) {
        if (locked) revert CouncilLocked();
        if (!isActive[msg.sender]) revert NotGuardian();
        if (!approvedTarget[target] || !approvedSelector[target][_selector(data)]) revert TargetNotAllowed();
        id = nextRecoveryId++;
        Recovery storage r = recoveries[id];
        r.proposer = msg.sender;
        r.target = target;
        r.calldataHash = keccak256(data);
        r.chainId = block.chainid;
        r.nonce = nonce;
        r.createdAt = uint64(block.timestamp);
        r.executeAfter = 0;
        r.expiresAt = uint64(block.timestamp + PROPOSAL_LIFETIME);
        r.approvals = 1;
        r.approved[msg.sender] = true;
        emit RecoveryProposed(id, msg.sender, target, r.calldataHash, 0, r.expiresAt);
        emit RecoveryApproved(id, msg.sender, 1);
    }

    function approveRecovery(uint256 id) external {
        if (locked) revert CouncilLocked();
        if (!isActive[msg.sender]) revert NotGuardian();
        Recovery storage r = recoveries[id];
        if (r.proposer == address(0) || r.vetoed || r.executed || block.timestamp > r.expiresAt) revert InvalidRecovery();
        if (r.approved[msg.sender]) revert AlreadyApproved();
        r.approved[msg.sender] = true;
        r.approvals++;
        emit RecoveryApproved(id, msg.sender, r.approvals);
        if (r.approvals == 5 && r.executeAfter == 0) {
            r.executeAfter = uint64(block.timestamp + RECOVERY_DELAY);
            r.expiresAt = uint64(uint256(r.executeAfter) + PROPOSAL_LIFETIME);
            emit RecoveryProposed(id, r.proposer, r.target, r.calldataHash, r.executeAfter, r.expiresAt);
        }
        if (r.approvals == 6 && !warning) {
            warning = true;
            emit WarningActivated(id, uint64(block.timestamp + VETO_WINDOW));
        }
        if (r.approvals == 7) {
            locked = true;
            standbyActivated = true;
            for (uint256 i; i < 7; ++i) isActive[active[i]] = false;
            for (uint256 i; i < 7; ++i) isActive[standby[i]] = true;
            emit CouncilLockedAndStandbyActivated();
        }
    }

    function vetoRecovery(uint256 id) external {
        if (msg.sender != lastHonestGuardian) revert NotGuardian();
        Recovery storage r = recoveries[id];
        if (r.proposer == address(0) || r.vetoed || r.executed || r.approvals < 6 || block.timestamp > uint256(r.createdAt) + VETO_WINDOW) revert InvalidRecovery();
        r.vetoed = true;
        emit RecoveryVetoed(id, msg.sender);
    }

    function executeRecovery(uint256 id, bytes calldata data) external nonReentrant {
        Recovery storage r = recoveries[id];
        if (r.proposer == address(0) || r.vetoed || r.executed || r.approvals < 5) revert InvalidRecovery();
        if (block.timestamp < r.executeAfter || block.timestamp > r.expiresAt) revert NotReady();
        if (r.chainId != block.chainid || keccak256(data) != r.calldataHash) revert InvalidRecovery();
        if (!approvedTarget[r.target] || !approvedSelector[r.target][_selector(data)]) revert TargetNotAllowed();
        r.executed = true;
        (bool ok, bytes memory result) = r.target.call(data);
        if (!ok) {
            r.executed = false;
            assembly { revert(add(result, 32), mload(result)) }
        }
        warning = false;
        emit RecoveryExecuted(id, msg.sender);
    }

    function _selector(bytes calldata data) internal pure returns (bytes4 sel) {
        if (data.length < 4) return bytes4(0);
        assembly { sel := calldataload(data.offset) }
    }

    uint256[40] private __gap;
}

contracts/registry/CollectionRegistry.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CatalystUUPS} from "../common/CatalystUUPS.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface ICATAPayments {
    function payFee(uint256 fee) external;
}

contract CollectionRegistry is CatalystUUPS {
    using SafeERC20 for IERC20;

    enum Tier { NONE, UNVERIFIED, VERIFIED, BLUE_CHIP }
    uint256 public constant BASE_REGISTRATION_FEE = 100 ether;
    uint256 public constant UNVERIFIED_ESCROW = 500 ether;
    uint256 public constant ESCROW_WINDOW = 180 days;
    uint256 public constant MAX_COLLECTION_NFTS = 20_000;

    struct Collection {
        Tier tier;
        uint64 registeredAt;
        uint64 escrowDeadline;
        uint32 stakedCount;
        uint256 escrowAmount;
        bool incidentFlag;
    }

    IERC20 public cata;
    address public staking;
    address public governance;
    mapping(address => Collection) private collections;
    address[] private collectionList;

    error InvalidCollection();
    error AlreadyRegistered();
    error NotAuthorized();
    error InvalidTier();
    error EscrowUnavailable();

    event CollectionRegistered(address indexed collection, Tier tier, address indexed registrar, uint256 fee, uint256 escrow);
    event TierChanged(address indexed collection, Tier oldTier, Tier newTier, bytes32 indexed proposalId);
    event IncidentFlagChanged(address indexed collection, bool flagged);
    event EscrowSettled(address indexed collection, address indexed recipient, uint256 amount, bool refunded);

    constructor() { _disableInitializers(); }

    function initialize(address cata_, address upgradeAuthority_, address governance_) external initializer {
        require(cata_ != address(0) && upgradeAuthority_ != address(0), "zero address");
        cata = IERC20(cata_);
        governance = governance_;
        __CatalystUUPS_init(upgradeAuthority_);
    }

    function setGovernance(address governance_) external onlyUpgradeAuthority {
        require(governance == address(0) && governance_ != address(0), "governance configured");
        governance = governance_;
    }

    function setStaking(address staking_) external onlyUpgradeAuthority {
        require(staking == address(0) && staking_ != address(0), "staking configured");
        staking = staking_;
    }

    function registerCollection(address collection, bool requestVerified) external {
        if (collection == address(0) || collection.code.length == 0) revert InvalidCollection();
        if (collections[collection].tier != Tier.NONE) revert AlreadyRegistered();
        uint256 fee = BASE_REGISTRATION_FEE;
        uint256 escrow = requestVerified ? 0 : UNVERIFIED_ESCROW;
        uint256 total = fee + escrow;
        cata.safeTransferFrom(msg.sender, address(this), total);
        // The registration fee is routed via token's fee distributor only if approved by the user.
        // This registry holds fee funds; settlement must be explicit and audited in deployment.
        collections[collection] = Collection({
            tier: requestVerified ? Tier.VERIFIED : Tier.UNVERIFIED,
            registeredAt: uint64(block.timestamp),
            escrowDeadline: uint64(block.timestamp + ESCROW_WINDOW),
            stakedCount: 0,
            escrowAmount: escrow,
            incidentFlag: false
        });
        collectionList.push(collection);
        emit CollectionRegistered(collection, collections[collection].tier, msg.sender, fee, escrow);
    }

    function setTier(address collection, Tier newTier, bytes32 proposalId) external {
        if (msg.sender != governance && msg.sender != upgradeAuthority) revert NotAuthorized();
        Collection storage c = collections[collection];
        if (c.tier == Tier.NONE || newTier == Tier.NONE) revert InvalidTier();
        Tier old = c.tier;
        c.tier = newTier;
        emit TierChanged(collection, old, newTier, proposalId);
    }

    function setIncidentFlag(address collection, bool flagged) external {
        if (msg.sender != governance && msg.sender != upgradeAuthority) revert NotAuthorized();
        if (collections[collection].tier == Tier.NONE) revert InvalidCollection();
        collections[collection].incidentFlag = flagged;
        emit IncidentFlagChanged(collection, flagged);
    }

    function settleEscrow(address collection, address recipient, bool refund) external {
        if (msg.sender != governance && msg.sender != upgradeAuthority) revert NotAuthorized();
        Collection storage c = collections[collection];
        if (c.tier == Tier.NONE || c.escrowAmount == 0) revert EscrowUnavailable();
        if (refund && (block.timestamp > c.escrowDeadline || c.tier != Tier.VERIFIED || c.incidentFlag)) revert EscrowUnavailable();
        uint256 amount = c.escrowAmount;
        c.escrowAmount = 0;
        cata.safeTransfer(recipient, amount);
        emit EscrowSettled(collection, recipient, amount, refund);
    }

    function getCollection(address collection) external view returns (Collection memory) { return collections[collection]; }
    function collectionCount() external view returns (uint256) { return collectionList.length; }
    function collectionAt(uint256 i) external view returns (address) { return collectionList[i]; }

    function noteStake(address collection, int256 delta) external {
        require(msg.sender == staking, "only staking");
        Collection storage c = collections[collection];
        require(c.tier != Tier.NONE, "not registered");
        if (delta > 0) {
            uint256 next = uint256(c.stakedCount) + uint256(delta);
            require(next <= MAX_COLLECTION_NFTS, "collection cap");
            c.stakedCount = uint32(next);
        } else {
            uint256 amount = uint256(-delta);
            require(amount <= c.stakedCount, "counter underflow");
            c.stakedCount -= uint32(amount);
        }
    }

    uint256[40] private __gap;
}

contracts/staking/CatalystStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CatalystUUPS} from "../common/CatalystUUPS.sol";
import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";

interface ICATAMint {
    function mintReward(address to, uint256 amount) external;
    function routeStakingFee(uint256 fee) external;
    function totalSupply() external view returns (uint256);
}
interface ICollectionRegistry {
    enum Tier { NONE, UNVERIFIED, VERIFIED, BLUE_CHIP }
    function getCollection(address) external view returns (
        Tier tier, uint64 registeredAt, uint64 escrowDeadline, uint32 stakedCount, uint256 escrowAmount, bool incidentFlag
    );
    function noteStake(address, int256) external;
}

contract CatalystStaking is CatalystUUPS, IERC721Receiver, ReentrancyGuardUpgradeable {
    using SafeERC20 for IERC20;

    uint256 public constant GLOBAL_CAP = 500_000_000;
    uint256 public constant TERM_CAP = 375_000_000;
    uint256 public constant PERMANENT_CAP = 125_000_000;
    uint256 public constant MAX_HARVEST_BATCH = 50;
    uint256 public constant ANNUAL_REWARD_CAP = 20_000_000 ether; // Proposed v1.1 default.
    uint256 public constant YEAR = 365 days;
    uint256 public constant HARVEST_FEE_BPS = 200; // Proposed default: 2%.
    uint256 public constant UNSTAKE_FEE_BPS = 100; // Proposed default: 1%.
    uint256 public constant BPS = 10_000;

    enum StakeType { TERM, PERMANENT }
    struct Position {
        address owner;
        address collection;
        uint256 tokenId;
        uint64 startedAt;
        uint64 lastHarvestAt;
        uint64 termEndsAt;
        StakeType stakeType;
        bool active;
    }

    ICATAMint public cata;
    IERC20 public cataTransfer;
    ICollectionRegistry public registry;
    address public governance;
    uint256 public termCount;
    uint256 public permanentCount;
    uint256 public rewardRatePerNFTPerDay; // Set at deployment; wei CATA per NFT per day.
    uint256 public annualWindowStart;
    uint256 public mintedInWindow;
    uint256 public totalStaked;
    uint256 public nextPositionId;
    mapping(uint256 => Position) public positions;
    mapping(address => mapping(address => mapping(uint256 => uint256))) public positionOf;
    mapping(address => uint256) public userActiveCount;
    mapping(uint256 => uint256) public dailyMinted; // UTC-day bucket used for true rolling 365-day accounting.

    error InvalidPosition();
    error CapExceeded();
    error NotOwner();
    error WrongTier();
    error TermNotEnded();
    error InvalidBatch();

    event Staked(uint256 indexed positionId, address indexed owner, address indexed collection, uint256 tokenId, StakeType stakeType, uint256 termEndsAt);
    event Harvested(uint256 indexed positionId, address indexed owner, uint256 gross, uint256 fee, uint256 net);
    event Unstaked(uint256 indexed positionId, address indexed owner, uint256 grossAccrued, uint256 fee);
    event RewardRateUpdated(uint256 oldRate, uint256 newRate);

    constructor() { _disableInitializers(); }

    function initialize(address cata_, address registry_, address governance_, address upgradeAuthority_, uint256 rewardRate_) external initializer {
        require(cata_ != address(0) && registry_ != address(0) && governance_ != address(0), "zero address");
        __ReentrancyGuard_init();
        __CatalystUUPS_init(upgradeAuthority_);
        cata = ICATAMint(cata_);
        cataTransfer = IERC20(cata_);
        registry = ICollectionRegistry(registry_);
        governance = governance_;
        rewardRatePerNFTPerDay = rewardRate_;
        annualWindowStart = block.timestamp;
        nextPositionId = 1;
    }

    function setGovernance(address governance_) external onlyUpgradeAuthority {
        require(governance == address(0) && governance_ != address(0), "governance configured");
        governance = governance_;
    }

    function setRewardRate(uint256 newRate) external {
        require(msg.sender == governance, "only governance");
        emit RewardRateUpdated(rewardRatePerNFTPerDay, newRate);
        rewardRatePerNFTPerDay = newRate;
    }

    function stake(address collection, uint256 tokenId, StakeType stakeType, uint64 termDuration) external nonReentrant {
        (ICollectionRegistry.Tier tier,,,,,) = registry.getCollection(collection);
        if (tier != ICollectionRegistry.Tier.VERIFIED && tier != ICollectionRegistry.Tier.UNVERIFIED) revert WrongTier();
        if (totalStaked >= GLOBAL_CAP) revert CapExceeded();
        if (stakeType == StakeType.TERM) {
            if (termCount >= TERM_CAP || termDuration < 1 days) revert CapExceeded();
            termCount++;
        } else {
            if (permanentCount >= PERMANENT_CAP) revert CapExceeded();
            permanentCount++;
        }
        require(positionOf[collection][msg.sender][tokenId] == 0, "already staked");
        IERC721(collection).safeTransferFrom(msg.sender, address(this), tokenId);
        uint256 id = nextPositionId++;
        uint64 ends = stakeType == StakeType.TERM ? uint64(block.timestamp + termDuration) : 0;
        positions[id] = Position(msg.sender, collection, tokenId, uint64(block.timestamp), uint64(block.timestamp), ends, stakeType, true);
        positionOf[collection][msg.sender][tokenId] = id;
        userActiveCount[msg.sender]++;
        totalStaked++;
        registry.noteStake(collection, 1);
        emit Staked(id, msg.sender, collection, tokenId, stakeType, ends);
    }

    function pendingReward(uint256 id) public view returns (uint256) {
        Position memory p = positions[id];
        if (!p.active) return 0;
        uint256 elapsed = block.timestamp - p.lastHarvestAt;
        uint256 reward = elapsed * rewardRatePerNFTPerDay / 1 days;
        uint256 headroom = cata.totalSupply() >= 1_000_000_000 ether ? 0 : 1_000_000_000 ether - cata.totalSupply();
        if (reward > headroom) reward = headroom;
        uint256 rolling = rollingMintedLast365Days();
        uint256 remaining = rolling >= ANNUAL_REWARD_CAP ? 0 : ANNUAL_REWARD_CAP - rolling;
        if (reward > remaining) reward = remaining;
        return reward;
    }

    function harvest(uint256[] calldata ids) external nonReentrant {
        if (ids.length == 0 || ids.length > MAX_HARVEST_BATCH) revert InvalidBatch();
        for (uint256 i; i < ids.length; ++i) {
            Position storage p = positions[ids[i]];
            if (!p.active) revert InvalidPosition();
            if (p.owner != msg.sender) revert NotOwner();
            uint256 gross = pendingReward(ids[i]);
            p.lastHarvestAt = uint64(block.timestamp);
            if (gross == 0) continue;
            uint256 fee = gross * HARVEST_FEE_BPS / BPS;
            uint256 net = gross - fee;
            _accountEmission(gross);
            if (net > 0) cata.mintReward(msg.sender, net);
            // Harvest fee is routed using the immutable 90/9/1 fee rule.
            if (fee > 0) {
                cata.mintReward(address(this), fee);
                _routeMintedFee(fee);
            }
            emit Harvested(ids[i], msg.sender, gross, fee, net);
        }
    }

    function unstake(uint256 id) external nonReentrant {
        Position storage p = positions[id];
        if (!p.active) revert InvalidPosition();
        if (p.owner != msg.sender) revert NotOwner();
        if (p.stakeType == StakeType.TERM && block.timestamp < p.termEndsAt) revert TermNotEnded();
        uint256 gross = pendingReward(id);
        p.active = false;
        p.lastHarvestAt = uint64(block.timestamp);
        _accountEmission(gross);
        uint256 fee = gross * UNSTAKE_FEE_BPS / BPS;
        if (gross > fee) cata.mintReward(msg.sender, gross - fee);
        if (fee > 0) {
            cata.mintReward(address(this), fee);
            _routeMintedFee(fee);
        }
        if (p.stakeType == StakeType.TERM) termCount--; else permanentCount--;
        totalStaked--;
        userActiveCount[msg.sender]--;
        delete positionOf[p.collection][msg.sender][p.tokenId];
        registry.noteStake(p.collection, -1);
        IERC721(p.collection).safeTransferFrom(address(this), msg.sender, p.tokenId);
        emit Unstaked(id, msg.sender, gross, fee);
    }

    /// @notice Sum emissions from the current UTC day and preceding 364 UTC days.
    /// The 365-slot loop is bounded and is used by harvest/unstake validation.
    function rollingMintedLast365Days() public view returns (uint256 total) {
        uint256 today = block.timestamp / 1 days;
        for (uint256 i; i < 365; ++i) {
            if (today < i) break;
            total += dailyMinted[today - i];
        }
    }

    function _accountEmission(uint256 amount) internal {
        uint256 rolling = rollingMintedLast365Days();
        require(amount <= ANNUAL_REWARD_CAP - (rolling > ANNUAL_REWARD_CAP ? ANNUAL_REWARD_CAP : rolling), "rolling annual cap");
        dailyMinted[block.timestamp / 1 days] += amount;
        mintedInWindow = rolling + amount; // legacy observable field; now represents rolling total
        annualWindowStart = block.timestamp;
    }

    function _routeMintedFee(uint256 fee) internal {
        uint256 burned = fee * 9000 / BPS;
        uint256 treasuryAmount = fee * 900 / BPS;
        uint256 maintainerAmount = fee - burned - treasuryAmount;
        // The fee was minted to this contract; token contract applies the immutable split.
        cata.routeStakingFee(fee);
        emit FeeReserveAccrued(fee, burned, treasuryAmount, maintainerAmount);
    }

    event FeeReserveAccrued(uint256 fee, uint256 burned, uint256 treasuryAmount, uint256 maintainerAmount);

    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }

    uint256[40] private __gap;
}

contracts/token/CATAToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {ERC20BurnableUpgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20BurnableUpgradeable.sol";
import {CatalystUUPS} from "../common/CatalystUUPS.sol";

/// @title Catalyst (CATA)
/// @notice 1bn hard cap; initial 100m allocation; after initialization only staking may mint.
/// Applicable fees are conserved using immutable 90/9/1 routing.
contract CATAToken is ERC20Upgradeable, ERC20BurnableUpgradeable, CatalystUUPS {
    uint256 public constant MAX_SUPPLY = 1_000_000_000 ether;
    uint256 public constant INITIAL_MINT = 100_000_000 ether;
    uint256 public constant BP_DENOMINATOR = 10_000;
    uint256 public constant BURN_BPS = 9_000;
    uint256 public constant TREASURY_BPS = 900;

    address public stakingContract;
    address public treasury;
    address public maintainer;
    address public configurationAuthority;
    bool public stakingConfigured;

    error SupplyCapExceeded();
    error OnlyStaking();
    error AlreadyConfigured();
    error InvalidAddress();
    error GenericRoleManagementDisabled();

    event InitialAllocationMinted(address indexed recipient, uint256 amount);
    event StakingContractConfigured(address indexed staking);
    event FeeDistributed(address indexed payer, uint256 fee, uint256 burned, uint256 treasuryAmount, uint256 maintainerAmount);
    event VoluntaryBurn(address indexed account, uint256 amount);

    constructor() { _disableInitializers(); }

    function initialize(
        address initialAllocation,
        address treasury_,
        address maintainer_,
        address upgradeAuthority_
    ) external initializer {
        if (initialAllocation == address(0) || treasury_ == address(0) ||
            maintainer_ == address(0) || upgradeAuthority_ == address(0)) revert InvalidAddress();
        __ERC20_init("Catalyst", "CATA");
        __ERC20Burnable_init();
        __CatalystUUPS_init(upgradeAuthority_);
        treasury = treasury_;
        maintainer = maintainer_;
        configurationAuthority = upgradeAuthority_;
        _mint(initialAllocation, INITIAL_MINT);
        emit InitialAllocationMinted(initialAllocation, INITIAL_MINT);
    }

    function setStakingContract(address staking_) external {
        if (msg.sender != configurationAuthority) revert Unauthorized();
        if (stakingConfigured) revert AlreadyConfigured();
        if (staking_ == address(0)) revert InvalidAddress();
        stakingContract = staking_;
        stakingConfigured = true;
        emit StakingContractConfigured(staking_);
    }

    function mintReward(address to, uint256 amount) external {
        if (msg.sender != stakingContract || !stakingConfigured) revert OnlyStaking();
        if (totalSupply() + amount > MAX_SUPPLY) revert SupplyCapExceeded();
        _mint(to, amount);
    }

    /// @notice Caller approves this contract for fee amount, then this function routes it.
    /// The caller must show these exact values in the DApp before wallet confirmation.
    function payFee(uint256 fee) external {
        if (fee == 0) revert InvalidAddress();
        _transfer(msg.sender, address(this), fee);
        uint256 burned = fee * BURN_BPS / BP_DENOMINATOR;
        uint256 treasuryAmount = fee * TREASURY_BPS / BP_DENOMINATOR;
        uint256 maintainerAmount = fee - burned - treasuryAmount;
        _burn(address(this), burned);
        _transfer(address(this), treasury, treasuryAmount);
        _transfer(address(this), maintainer, maintainerAmount);
        emit FeeDistributed(msg.sender, fee, burned, treasuryAmount, maintainerAmount);
    }

    /// @notice Routes fees already minted to the staking contract using the immutable 90/9/1 split.
    /// Only the configured staking contract may call this method.
    function routeStakingFee(uint256 fee) external {
        if (msg.sender != stakingContract || !stakingConfigured) revert OnlyStaking();
        if (fee == 0 || balanceOf(msg.sender) < fee) revert InvalidAddress();
        uint256 burned = fee * BURN_BPS / BP_DENOMINATOR;
        uint256 treasuryAmount = fee * TREASURY_BPS / BP_DENOMINATOR;
        uint256 maintainerAmount = fee - burned - treasuryAmount;
        _burn(msg.sender, burned);
        _transfer(msg.sender, treasury, treasuryAmount);
        _transfer(msg.sender, maintainer, maintainerAmount);
        emit FeeDistributed(msg.sender, fee, burned, treasuryAmount, maintainerAmount);
    }

    function voluntaryBurn(uint256 amount) external {
        _burn(msg.sender, amount);
        emit VoluntaryBurn(msg.sender, amount);
    }

    function changeFeeRecipients(address, address) external pure {
        revert("fee recipients fixed in this release");
    }

    function grantRole(bytes32, address) public pure { revert GenericRoleManagementDisabled(); }
    function revokeRole(bytes32, address) public pure { revert GenericRoleManagementDisabled(); }
    function renounceRole(bytes32, address) public pure { revert GenericRoleManagementDisabled(); }

    uint256[40] private __gap;
}

